#include "networking.h"
#include <ArduinoJson.h>
constexpr char WIFI_SSID[]="CHANGE_ME",WIFI_PASSWORD[]="CHANGE_ME",LAPTOP_IP[]="192.168.1.10",DRONE_ID[]="wake-01";constexpr uint16_t TELEMETRY_PORT=5005,COMMAND_PORT=5007;
void WakeNetworking::begin(){laptop_.fromString(LAPTOP_IP);WiFi.begin(WIFI_SSID,WIFI_PASSWORD);commandUdp_.begin(COMMAND_PORT);}void WakeNetworking::update(){if(WiFi.status()!=WL_CONNECTED&&millis()-lastReconnectMs_>5000){lastReconnectMs_=millis();WiFi.reconnect();}}
void WakeNetworking::publishTelemetry(const TelemetryPacket&p){if(WiFi.status()!=WL_CONNECTED)return;StaticJsonDocument<768>d;d["protocol_version"]=2;d["type"]="telemetry";d["drone_id"]=DRONE_ID;d["sequence"]=p.sequence;d["timestamp_us"]=p.timestampUs;d["battery_v"]=p.batteryV;d["validity"]=p.validity;JsonArray a=d.createNestedArray("accel_body_g"),g=d.createNestedArray("gyro_body"),r=d.createNestedArray("attitude_rpy_rad"),m=d.createNestedArray("motors");for(int i=0;i<3;i++){a.add(p.accelG[i]);g.add(p.gyro[i]);r.add(p.attitudeRad[i]);}for(int i=0;i<4;i++)m.add(p.motors[i]);JsonObject h=d.createNestedObject("health");h["achieved_msp_hz"]=p.achievedHz;h["msp_timeouts"]=p.mspTimeouts;h["wifi_rssi_dbm"]=WiFi.RSSI();char out[768];size_t n=serializeJson(d,out);telemetryUdp_.beginPacket(laptop_,TELEMETRY_PORT);telemetryUdp_.write((uint8_t*)out,n);telemetryUdp_.endPacket();}
